style.css:
/* 全局设置：中文为宋体，英文为 Times New Roman */
* {
    font-family: "Times New Roman", "SimSun", serif !important;
}

/* 针对中文内容单独设置 */
:lang(zh), :lang(zh-CN), :lang(zh-TW), :lang(zh-HK) {
    font-family: "SimSun", serif !important;
}

/* 针对英文内容单独设置 */
:lang(en) {
    font-family: "Times New Roman", serif !important;
}
